import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CNDaxUod.js";const p=JSON.parse('{"title":"5. Directory and group rosters","description":"","frontmatter":{},"headers":[],"relativePath":"guide/directory.md","filePath":"guide/directory.md"}'),n={name:"guide/directory.md"};function s(i,e,d,h,l,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="_5-directory-and-group-rosters" tabindex="-1">5. Directory and group rosters <a class="header-anchor" href="#_5-directory-and-group-rosters" aria-label="Permalink to &quot;5. Directory and group rosters&quot;">​</a></h1><p>Step 5 of the <a href="./getting-started.html">setup path</a>, optional. AsyncUp can read your Workspace directory as its service account. That buys three things:</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it needs</th></tr></thead><tbody><tr><td><strong>Rosters that follow a Google Group</strong>: joiners are added, leavers dropped</td><td>The admin role below</td></tr><tr><td><strong>Google Groups in a space</strong>: on a roster picked from the space, members of a group in the space count as in it</td><td>The admin role below</td></tr><tr><td><strong>User lookups</strong>: Workspace admins recognised at Google sign-in, accounts outside the Workspace refused, SAML and SCIM users linked to their Chat identity straight away, emails found for Calendar out-of-office</td><td>The admin role below</td></tr><tr><td><strong>Calendar out-of-office</strong>: people with an <em>Out of office</em> event are marked away</td><td><a href="#calendar-ooo">Domain-wide delegation</a></td></tr></tbody></table><p>No domain-wide delegation is needed for the first two. Google recommends an admin role on the service account instead, and that is what AsyncUp uses.</p><h2 id="admin-role" tabindex="-1">Give the service account an admin role <a class="header-anchor" href="#admin-role" aria-label="Permalink to &quot;Give the service account an admin role {#admin-role}&quot;">​</a></h2><p>You need a Workspace super admin for this, once.</p><ol><li>In the Google Cloud project that holds the service account, enable the <strong>Admin SDK API</strong> (<strong>APIs &amp; Services → Library</strong>).</li><li>In the <a href="https://admin.google.com" target="_blank" rel="noreferrer">Admin console</a>, go to <strong>Account → Admin roles → Create new role</strong>. Name it, e.g. <em>AsyncUp Directory Reader</em>.</li><li>Under <strong>Admin API privileges</strong>, tick only <strong>Groups › Read</strong> and <strong>Users › Read</strong>. Nothing else.</li><li>Open the new role and choose <strong>Assign service accounts</strong>. Enter the service account&#39;s email, e.g. <code>asyncup@&lt;project&gt;.iam.gserviceaccount.com</code>. Assign it to the service account, not to a person: AsyncUp calls Google as the service account.</li></ol><p>The built-in <strong>Groups Reader</strong> role is not enough on its own. It has no <strong>Users › Read</strong>, which AsyncUp needs to resolve group members and look people up.</p><p>A new role can take up to about 15 minutes to apply. Until then:</p><ul><li>a roster sync says it can&#39;t read the group, and names the role to grant;</li><li>Google sign-in still works, but everyone signs in as a regular user, and the server log says the service account can&#39;t read users.</li></ul><h2 id="rosters-that-follow-a-google-group" tabindex="-1">Rosters that follow a Google Group <a class="header-anchor" href="#rosters-that-follow-a-google-group" aria-label="Permalink to &quot;Rosters that follow a Google Group&quot;">​</a></h2><p>A standup can follow a Google Group instead of people picked from its space. Everyone in the group is on the standup, including members of nested groups.</p><ul><li><strong>When you create a standup</strong>: under <strong>People</strong>, set <strong>Who is on it</strong> to <em>Everyone in a Google Group</em> and enter the <strong>Google Group email</strong>.</li><li><strong>For an existing standup</strong>: <strong>Settings → People → Roster</strong>, choose <em>Everyone in a Google Group</em>, enter the group&#39;s email and save.</li></ul><p>The roster syncs straight away, then every hour, again in the hour before each run, and before <strong>Run now</strong>. <strong>Sync now</strong> syncs on demand and reports who was added, who was removed, and who was skipped and why: people outside your Workspace, suspended accounts and accounts that aren&#39;t active.</p><p>How a group roster behaves:</p><table tabindex="0"><thead><tr><th>Event</th><th>Result</th></tr></thead><tbody><tr><td>Someone joins the group</td><td>Added with the default setup: prompted, required, following the standup&#39;s days</td></tr><tr><td>Someone leaves the group</td><td>Dropped from the standup. Their history stays</td></tr><tr><td>You untick someone in the People grid</td><td>They stay off, even though they&#39;re still in the group</td></tr><tr><td>You add someone by hand who isn&#39;t in the group</td><td>They stay on</td></tr></tbody></table><p>Group joiners are not checked for whether the bot can DM them. Make sure the app reaches everyone in the group (<a href="./distribution.html">step 4</a>).</p><h2 id="space-rosters" tabindex="-1">Rosters picked from the space <a class="header-anchor" href="#space-rosters" aria-label="Permalink to &quot;Rosters picked from the space {#space-rosters}&quot;">​</a></h2><p>A roster picked from the space is checked against the space on the same schedule: every hour, and again in the hour before each run.</p><table tabindex="0"><thead><tr><th>Event</th><th>Result</th></tr></thead><tbody><tr><td>Someone on the roster leaves the space</td><td>Taken off the standup, and out of today&#39;s run unless they&#39;ve answered. Their history stays</td></tr><tr><td>They rejoin the space</td><td>Put back with their old settings, from the next run</td></tr><tr><td>You take someone off by hand</td><td>They stay off, even if they rejoin</td></tr><tr><td>Someone was added from outside the space (API or MCP)</td><td>Never taken off, because they were never seen in the space</td></tr><tr><td>Someone joins the space</td><td>Nothing. You pick who is on the standup</td></tr></tbody></table><p>When a Google Group is a member of the space, its people count as in the space. AsyncUp reads the group with the admin role above. If it can&#39;t, or Google Chat doesn&#39;t answer, or the space lists nobody, nobody is taken off and <strong>Settings → People → Last sync</strong> says why.</p><p>The first check after an upgrade only notes who is in the space, so nobody comes off until they leave after that.</p><h2 id="user-lookups" tabindex="-1">User lookups <a class="header-anchor" href="#user-lookups" aria-label="Permalink to &quot;User lookups&quot;">​</a></h2><p>With a service-account key stored, AsyncUp looks people up as the service account:</p><table tabindex="0"><thead><tr><th>Where</th><th>Effect</th></tr></thead><tbody><tr><td>Google sign-in</td><td>Accounts the Directory doesn&#39;t know are refused, suspended accounts are refused, and Workspace super or delegated admins get the admin console</td></tr><tr><td>SAML sign-in</td><td>The person is linked to their Chat identity on first sign-in, and Workspace admins get the admin console. Accounts the Directory doesn&#39;t know are still let in: the IdP vouched for them</td></tr><tr><td>SCIM provisioning</td><td>New users are linked to their Chat identity by email</td></tr><tr><td>Calendar out-of-office</td><td>People&#39;s emails are found before they have ever used the bot</td></tr></tbody></table><p>If the service account can&#39;t read users, every one of these falls back to working without the Directory: Google sign-in lets the person in as a regular user, and SAML users are linked the first time they use the bot.</p><h3 id="directory-through-delegation-legacy" tabindex="-1">Directory through delegation (legacy) <a class="header-anchor" href="#directory-through-delegation-legacy" aria-label="Permalink to &quot;Directory through delegation (legacy)&quot;">​</a></h3><p><strong>Settings › Google Chat → Directory through delegation (legacy)</strong> sets a <strong>Workspace admin to act as</strong>, which moves Directory lookups from the admin role to domain-wide delegation, impersonating that admin. Leave it <strong>off</strong> with the admin role in place.</p><p>Earlier versions needed delegation for lookups, and installs set up that way keep working. If you deliberately want lookups through delegation, turn it on, enter an admin&#39;s email, and delegate <code>https://www.googleapis.com/auth/admin.directory.user.readonly</code> to the service account (see the steps below). Calendar out-of-office never uses this setting or the admin email.</p><h2 id="calendar-ooo" tabindex="-1">Calendar out-of-office <a class="header-anchor" href="#calendar-ooo" aria-label="Permalink to &quot;Calendar out-of-office {#calendar-ooo}&quot;">​</a></h2><p>This needs <strong>domain-wide delegation</strong>, because AsyncUp reads each person&#39;s calendar as that person. It does not use the Workspace admin email.</p><ol><li>Find the service account&#39;s <strong>OAuth 2 client ID</strong>, a long number. It is shown as <em>Client ID for domain-wide delegation</em> under <strong>Settings › Google Chat → Service account</strong>, in the guided setup when you switch Calendar out-of-office on, and in the Cloud console on the service account&#39;s page.</li><li>In the Admin console: <strong>Security → Access and data control → API controls → Domain-wide delegation → Add new</strong>. Enter the client ID and the scope <code>https://www.googleapis.com/auth/calendar.events.readonly</code>.</li><li>Enable the <strong>Google Calendar API</strong> in the Cloud project.</li><li>In AsyncUp, switch <strong>Calendar out-of-office</strong> on: in the guided setup&#39;s service-account step, or under <strong>Settings › General</strong>.</li></ol><p>The setting is off in a new install. Turn it on only after delegating: without the delegation, every calendar check fails, nobody is marked away, and each failure is logged.</p><p>When a run opens, people with an <em>Out of office</em> event that day are marked away, listed under <em>Away</em> and never counted as missing. AsyncUp needs each person&#39;s email to check their calendar: it comes from the Directory (the admin role above), or is learned the first time the person uses the bot.</p>',34)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
